1: #!/usr/bin/env node
2: import { readFile } from "node:fs/promises";
3: import { executeActionCommand } from "./action-command.js";
4: import { jsonLineActionTransport } from "./action-protocol.js";
5: import { ActionContextError } from "./current-run-chain.js";
6: import { TrustedChangeCoordinationError } from "./trusted-change-coordination.js";
7: import { OpenSpecObservationError } from "../domain/openspec-observation.js";
8: import { ManagedToolResolutionError } from "../domain/managed-tool-resolution.js";
9: import {
10:   loadManagerInstallation,
11:   ManagerInstallationError,
12: } from "../internal/manager-installation.js";
13: 
14: import {
15:   FoundationCliCommandError,
16:   executeFoundationCliRequest,
17: } from "./foundation-cli.js";
18: import {
19:   FoundationCliInputError,
20:   parseFoundationCliArguments,
21:   parseFoundationCliRequest,
22:   parseFoundationCliRequestJson,
23: } from "./request.js";
24: 
25: interface CliFailureEnvelope {
26:   readonly kind: "error";
27:   readonly error: {
28:     readonly kind: string;
29:   };
30: }
31: 
32: function writeJson(value: unknown): void {
33:   process.stdout.write(`${JSON.stringify(value)}\n`);
34: }
35: 
36: function failure(kind: string): CliFailureEnvelope {
37:   return Object.freeze({
38:     kind: "error",
39:     error: Object.freeze({ kind }),
40:   });
41: }
42: 
43: async function main(): Promise<number> {
44:   try {
45:     const { command, inputPath } = parseFoundationCliArguments(
46:       process.argv.slice(2),
47:     );
48:     let requestText: string;
49:     try {
50:       requestText = await readFile(inputPath, "utf8");
51:     } catch (error) {
52:       throw new FoundationCliInputError(
53:         "invalid-arguments",
54:         "cannot read --input request file",
55:         { cause: error },
56:       );
57:     }
58:     const raw = parseFoundationCliRequestJson(requestText);
59:     const request = parseFoundationCliRequest(command, raw);
60:     if (request.command === "action") {
61:       return executeActionCommand(
62:         request.request,
63:         loadManagerInstallation(),
64:         jsonLineActionTransport(process.stdin, process.stdout),
65:       );
66:     }
67:     writeJson(
68:       await executeFoundationCliRequest(request, loadManagerInstallation()),
69:     );
70:     return 0;
71:   } catch (error) {
72:     const actionInput = process.argv[2] === "action";
73:     if (
74:       error instanceof FoundationCliInputError ||
75:       error instanceof FoundationCliCommandError ||
76:       error instanceof ManagerInstallationError ||
77:       error instanceof ActionContextError ||
78:       error instanceof TrustedChangeCoordinationError ||
79:       error instanceof OpenSpecObservationError ||
80:       error instanceof ManagedToolResolutionError
81:     ) {
82:       if (actionInput) {
83:         writeJson({
84:           kind: "error",
85:           error: {
86:             kind: error.kind,
87:             stage: "context",
88:             runId: null,
89:             persistence: "none",
90:           },
91:         });
92:         return 2;
93:       }
94:       writeJson(
95:         error instanceof ActionContextError
96:           ? {
97:               kind: "error",
98:               error: {
99:                 kind: error.kind,
100:                 message: error.message,
101:                 candidates: error.candidates,
102:               },
103:             }
104:           : failure(error.kind),
105:       );
106:       return 2;
107:     }
108:     writeJson(
109:       actionInput
110:         ? {
111:             kind: "error",
112:             error: {
113:               kind: "internal-error",
114:               stage: "context",
115:               runId: null,
116:               persistence: "none",
117:             },
118:           }
119:         : failure("internal-error"),
120:     );
121:     return 3;
122:   }
123: }
124: 
125: process.exitCode = await main();
