31: export type FoundationCliFailureKind =
32:   | "invalid-current-run"
33:   | "run-read-failed"
34:   | "run-identity-mismatch"
35:   | "managed-tool-integration-failed"
36:   | "openspec-integration-failed"
37:   | "coordination-resolution-failed"
38:   | "invalid-checkpoint-authority";
