40: export class FoundationCliCommandError extends Error {
41:   readonly kind: FoundationCliFailureKind;
42: 
43:   constructor(
44:     kind: FoundationCliFailureKind,
45:     message: string,
46:     options?: ErrorOptions,
47:   ) {
48:     super(message, options);
49:     this.name = "FoundationCliCommandError";
50:     this.kind = kind;
51:   }
52: }
53: 
54: function fail(kind: FoundationCliFailureKind, message: string): never {
55:   throw new FoundationCliCommandError(kind, message);
56: }
