58: async function statusCommand(
59:   request: StatusRequest,
60:   installation: ManagerInstallation,
61: ) {
62:   const context = await resolveActionContext(request, installation);
63:   const selected = context.selected;
64:   const current = selected?.history.current;
65:   return {
66:     kind: "status" as const,
67:     status: context.status,
68:     repositoryRoot: context.repositoryRoot,
69:     deliveryId: selected?.deliveryId ?? null,
70:     changeId: selected?.changeId ?? null,
71:     changeState: selected?.changeState ?? null,
72:     currentRun: current
73:       ? {
74:           runId: current.context.runId,
75:           actionId: current.context.actionIdentity.actionId,
76:           state: current.context.lifecycleState,
77:           role: current.context.role,
78:         }
79:       : null,
80:     openSpec: context.openSpec,
81:   };
82: }
83: 
84: async function nextCommand(
85:   request: NextRequest,
86:   installation: ManagerInstallation,
87: ) {
88:   const context = await resolveActionContext(request, installation);
89:   const selected = context.selected;
90:   if (selected === null || selected.history.kind === "bootstrap-history") {
91:     return {
92:       kind: "next" as const,
93:       status: context.status,
94:       decision: null,
95:       checkpoint: null,
96:     };
97:   }
98:   const policyDecision = policyForRecord(selected.history.current, {
99:     deliveryId: selected.deliveryId,
100:     changeId: selected.changeId,
101:     changeState: selected.changeState,
102:     ...(Object.hasOwn(request, "ownerCorrection")
103:       ? { ownerCorrection: request.ownerCorrection }
104:       : {}),
105:   });
106:   let ownerAuthority: OwnerAuthorityFact | null = null;
107:   if (
108:     request.checkpointAuthority !== undefined &&
109:     request.checkpointAuthority !== null
110:   ) {
111:     if (!isOwnerAuthorityFact(request.checkpointAuthority))
112:       fail("invalid-checkpoint-authority", "Invalid checkpointAuthority");
113:     ownerAuthority = request.checkpointAuthority;
114:   }
115:   return {
116:     kind: "next" as const,
117:     decision: policyDecision,
118:     checkpoint: evaluateCheckpointAuthorization({
119:       policyDecision,
120:       ownerAuthority,
121:       deliveryId: selected.deliveryId,
122:       changeId: selected.changeId,
123:     }),
124:   };
125: }
