127: type DoctorDiagnostic =
128:   | {
129:       readonly id: "openspec-runtime";
130:       readonly status: "pass";
131:       readonly version: string;
132:     }
133:   | {
134:       readonly id: "openspec-root";
135:       readonly status: "pass";
136:       readonly activeChangeCount: number;
137:     }
138:   | {
139:       readonly id: "openspec-runtime" | "openspec-root";
140:       readonly status: "fail";
141:       readonly diagnosticKind: string;
142:     };
143: 
144: async function runtimeDiagnostic(
145:   request: DoctorRequest,
146:   toolId: "openspec",
147:   installation: ManagerInstallation,
148: ): Promise<DoctorDiagnostic> {
149:   try {
150:     const tool = await resolveManagedTool({
151:       flowkitHome: request.flowkitHome,
152:       installation,
153:       toolId,
154:     });
155:     return Object.freeze({
156:       id: `${toolId}-runtime`,
157:       status: "pass",
158:       version: tool.version,
159:     });
160:   } catch (error) {
161:     if (error instanceof ManagedToolResolutionError) {
162:       return Object.freeze({
163:         id: `${toolId}-runtime`,
164:         status: "fail",
165:         diagnosticKind: error.kind,
166:       });
167:     }
168:     throw error;
169:   }
170: }
171: 
172: async function openspecRootDiagnostic(
173:   request: DoctorRequest,
174:   installation: ManagerInstallation,
175: ): Promise<DoctorDiagnostic> {
176:   try {
177:     const observation = await observeOpenSpecActiveChanges({
178:       ...request,
179:       installation,
180:     });
181:     return Object.freeze({
182:       id: "openspec-root",
183:       status: "pass",
184:       activeChangeCount: observation.changeIds.length,
185:     });
186:   } catch (error) {
187:     if (
188:       error instanceof OpenSpecObservationError ||
189:       error instanceof ManagedToolResolutionError
190:     ) {
191:       return Object.freeze({
192:         id: "openspec-root",
193:         status: "fail",
194:         diagnosticKind: error.kind,
195:       });
196:     }
197:     throw error;
198:   }
199: }
200: 
201: async function doctorCommand(
202:   request: DoctorRequest,
203:   installation: ManagerInstallation,
204: ) {
205:   const diagnostics = await Promise.all([
206:     runtimeDiagnostic(request, "openspec", installation),
207:     openspecRootDiagnostic(request, installation),
208:   ]);
209:   return Object.freeze({
210:     kind: "doctor" as const,
211:     status: diagnostics.every((entry) => entry.status === "pass")
212:       ? ("pass" as const)
213:       : ("fail" as const),
214:     diagnostics: Object.freeze(diagnostics),
215:   });
216: }
217: 
218: export type FoundationCliResult =
219:   | Awaited<ReturnType<typeof statusCommand>>
220:   | Awaited<ReturnType<typeof nextCommand>>
221:   | Awaited<ReturnType<typeof doctorCommand>>;
222: 
223: export async function executeFoundationCliRequest(
224:   input: Exclude<FoundationCliRequest, { command: "action" }>,
225:   installation: ManagerInstallation = loadManagerInstallation(),
226: ): Promise<FoundationCliResult> {
227:   switch (input.command) {
228:     case "status":
229:       return statusCommand(input.request, installation);
230:     case "next":
231:       return nextCommand(input.request, installation);
232:     case "doctor":
233:       return doctorCommand(input.request, installation);
234:   }
235: }
236: 
237: export type { PolicyDecision, CheckpointAuthorization };
