13: export class ActionContextError extends Error {
14:   constructor(
15:     readonly kind:
16:       | "context-ambiguous"
17:       | "context-inconsistent"
18:       | "context-missing"
19:       | "run-chain-invalid",
20:     message: string,
21:     readonly candidates: readonly {
22:       deliveryId: string;
23:       changeId: string;
24:     }[] = [],
25:   ) {
26:     super(message);
27:     this.name = "ActionContextError";
28:   }
29: }
