31: export function policyForRecord(
32:   record: DurableRunRecord | null,
33:   input: {
34:     deliveryId: DeliveryId;
35:     changeId: ChangeId;
36:     changeState: string;
37:     ownerCorrection?: unknown;
38:   },
39: ) {
40:   return evaluatePolicyAndNextBoundary({
41:     deliveryId: input.deliveryId,
42:     changeId: input.changeId,
43:     changeState: input.changeState,
44:     ...(Object.hasOwn(input, "ownerCorrection")
45:       ? { ownerCorrection: input.ownerCorrection }
46:       : {}),
47:     currentAction:
48:       record === null
49:         ? null
50:         : {
51:             identity: record.context.actionIdentity,
52:             state: record.context.lifecycleState,
53:           },
54:     terminalRunContext:
55:       record?.context.lifecycleState === "terminal" ? record.context : null,
56:     terminalResult:
57:       record?.context.lifecycleState === "terminal" ? record.result : null,
58:   });
59: }
60: 
61: function invalid(message: string): never {
62:   throw new ActionContextError("run-chain-invalid", message);
63: }
64: 
65: export function resolveRunChain(
66:   records: readonly DurableRunRecord[],
67: ): DurableRunRecord | null {
68:   if (records.length === 0) return null;
69:   const byId = new Map(records.map((record) => [record.context.runId, record]));
70:   const sequences = new Set(
71:     records.map((record) => record.context.occurrence.sequence),
72:   );
73:   if (byId.size !== records.length || sequences.size !== records.length)
74:     invalid("Duplicate Run identity or sequence");
75:   const roots = records.filter(
76:     (record) => record.context.previousRunId === null,
77:   );
78:   if (
79:     roots.length !== 1 ||
80:     roots[0].context.actionIdentity.actionId !== "explore"
81:   )
82:     invalid("Expected one initial Explore root");
83:   const children = new Map<string, DurableRunRecord>();
84:   for (const record of records) {
85:     const { context, result } = record;
86:     if (
87:       context.role !==
88:       expectedExecutionRoleForAction(context.actionIdentity.actionId)
89:     )
90:       invalid(`Wrong Role: ${context.runId}`);
91:     if (context.lifecycleState === null)
92:       invalid(`Missing lifecycle: ${context.runId}`);
93:     if (
94:       result.verificationVerdict !== null ||
95:       (context.role === "author"
96:         ? result.reviewerVerdict !== null
97:         : result.authorConclusion !== null)
98:     )
99:       invalid(`Wrong outcome Role: ${context.runId}`);
100:     if (context.lifecycleState === "prepared") {
101:       const failure = result.facts.invocationFailure;
102:       if (
103:         !failure ||
104:         typeof failure !== "object" ||
105:         Array.isArray(failure) ||
106:         Object.keys(failure).sort().join(",") !== "kind,stage" ||
107:         typeof failure.kind !== "string" ||
108:         failure.kind.length === 0 ||
109:         !["execution", "evidence", "admission"].includes(
110:           String(failure.stage),
111:         ) ||
112:         [
113:           result.authorConclusion,
114:           result.reviewerVerdict,
115:           result.verificationVerdict,
116:           result.nextBoundary,
117:         ].some((value) => value !== null)
118:       )
119:         invalid(`Incomplete prepared failure: ${context.runId}`);
120:     } else {
121:       if (Object.hasOwn(result.facts, "invocationFailure"))
122:         invalid(`Terminal invocationFailure: ${context.runId}`);
123:       const own = policyForRecord(record, {
124:         ...context.actionIdentity,
125:         changeState:
126:           context.actionIdentity.actionId === "archive"
127:             ? "completed"
128:             : "active",
129:       });
130:       if (
131:         own.kind === "blocked" &&
132:         !(
133:           context.role === "author" &&
134:           result.authorConclusion === "FAIL" &&
135:           result.nextBoundary === null
136:         )
137:       )
138:         invalid(`Invalid terminal outcome: ${context.runId}`);
139:     }
140:     const parentId = context.previousRunId;
141:     if (parentId === null) continue;
142:     const parent = byId.get(parentId);
143:     if (!parent || children.has(parentId))
144:       invalid(`Missing parent or fork: ${context.runId}`);
145:     if (
146:       parent.context.actionIdentity.deliveryId !==
147:         context.actionIdentity.deliveryId ||
148:       parent.context.actionIdentity.changeId !== context.actionIdentity.changeId
149:     )
150:       invalid(`Cross-target parent: ${context.runId}`);
151:     const input = {
152:       ...context.actionIdentity,
153:       changeState:
154:         parent.context.actionIdentity.actionId === "archive"
155:           ? "completed"
156:           : "active",
157:     };
158:     let boundary = policyForRecord(parent, input);
159:     if (
160:       (boundary.kind !== "ready-action" ||
161:         boundary.actionId !== context.actionIdentity.actionId) &&
162:       context.ownerAuthority !== null
163:     ) {
164:       boundary = policyForRecord(parent, {
165:         ...input,
166:         ownerCorrection: {
167:           requestedAction: context.actionIdentity.actionId,
168:           authority: context.ownerAuthority,
169:         },
170:       });
171:     }
172:     if (
173:       boundary.kind !== "ready-action" ||
174:       boundary.actionId !== context.actionIdentity.actionId
175:     )
176:       invalid(`Illegal Policy edge: ${parentId} -> ${context.runId}`);
177:     children.set(parentId, record);
178:   }
179:   const visited = new Set<string>();
180:   let tip = roots[0];
181:   while (true) {
182:     if (visited.has(tip.context.runId)) invalid("Run cycle");
183:     visited.add(tip.context.runId);
184:     const child = children.get(tip.context.runId);
185:     if (!child) break;
186:     tip = child;
187:   }
188:   if (visited.size !== records.length) invalid("Disconnected Run history");
189:   return tip;
190: }
