192: export async function readSelectedRunChain(input: {
193:   repositoryRoot: string;
194:   deliveryId: DeliveryId;
195:   changeId: ChangeId;
196: }) {
197:   const root = path.join(
198:     input.repositoryRoot,
199:     ".flowkit",
200:     "runs",
201:     input.deliveryId,
202:   );
203:   let entries: Dirent[];
204:   try {
205:     entries = await readdir(root, { withFileTypes: true });
206:   } catch (error) {
207:     if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
208:     entries = [];
209:   }
210:   const matching = entries.filter(
211:     (entry) =>
212:       entry.name === input.changeId ||
213:       entry.name.endsWith(`-${input.changeId}`),
214:   );
215:   if (matching.length > 1)
216:     throw new ActionContextError(
217:       "context-ambiguous",
218:       `Multiple Run groups for ${input.changeId}`,
219:     );
220:   if (matching.length === 0)
221:     return {
222:       kind: "canonical" as const,
223:       changeStartSequence: 1,
224:       records: [],
225:       current: null,
226:     };
227:   const group = matching[0];
228:   if (!group.isDirectory()) invalid(`Invalid Run group: ${group.name}`);
229:   if (group.name === input.changeId) {
230:     const groupRoot = path.join(root, group.name);
231:     const runs = await readdir(groupRoot, { withFileTypes: true });
232:     if (runs.length === 0) invalid("Empty unmarked bootstrap group");
233:     for (const entry of runs) {
234:       if (!entry.isDirectory())
235:         invalid(`Invalid bootstrap occurrence: ${entry.name}`);
236:       for (const name of ["context.json", "result.json"]) {
237:         const record = JSON.parse(
238:           await readFile(path.join(groupRoot, entry.name, name), "utf8"),
239:         ) as Record<string, unknown>;
240:         if (
241:           record.canonicalFlowkitRuntimeRun !== false ||
242:           record.executionMode !== "independent-bootstrap" ||
243:           record.deliveryId !== input.deliveryId ||
244:           record.changeId !== input.changeId ||
245:           record.runId !== entry.name ||
246:           typeof record.kind !== "string" ||
247:           !record.kind.startsWith("external-orchestrator-")
248:         )
249:           invalid(`Unmarked bootstrap history: ${entry.name}`);
250:       }
251:       await readFile(path.join(groupRoot, entry.name, "action.md"));
252:     }
253:     return {
254:       kind: "bootstrap-history" as const,
255:       changeStartSequence: null,
256:       records: [],
257:       current: null,
258:     };
259:   }
260:   const prefix = group.name.slice(0, -(input.changeId.length + 1));
261:   const sequence = Number(prefix);
262:   if (!isRunSequence(sequence) || String(sequence).padStart(3, "0") !== prefix)
263:     invalid(`Invalid Run group prefix: ${group.name}`);
264:   let records;
265:   try {
266:     records = await listChangeRunHistory({
267:       ...input,
268:       changeStartSequence: sequence,
269:     });
270:   } catch (error) {
271:     invalid(error instanceof Error ? error.message : "Run history read failed");
272:   }
273:   if (records.length === 0) invalid("Empty canonical Run group");
274:   return {
275:     kind: "canonical" as const,
276:     changeStartSequence: sequence,
277:     records,
278:     current: resolveRunChain(records),
279:   };
280: }
