110: function isRecord(value: unknown): value is Record<string, unknown> {
111:   if (typeof value !== "object" || value === null || Array.isArray(value)) {
112:     return false;
113:   }
114:   const proto = Object.getPrototypeOf(value);
115:   return proto === Object.prototype || proto === null;
