118: function hasExactlyFields(
119:   value: Record<string, unknown>,
120:   fields: readonly string[],
121: ): boolean {
122:   const keys = Object.keys(value);
123:   return (
124:     keys.length === fields.length &&
125:     fields.every((field) => Object.hasOwn(value, field))
126:   );
127: }
