152: export function isCanonicalRunDate(value: unknown): value is string {
153:   if (typeof value !== "string" || !/^\d{8}$/.test(value)) return false;
154: 
155:   const year = Number(value.slice(0, 4));
156:   const month = Number(value.slice(4, 6));
157:   const day = Number(value.slice(6, 8));
158:   if (year < 1 || year > 9999 || month < 1 || month > 12 || day < 1) {
159:     return false;
160:   }
161: 
162:   const leapYear = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
163:   const daysInMonth = [
164:     31,
165:     leapYear ? 29 : 28,
166:     31,
167:     30,
168:     31,
169:     30,
170:     31,
171:     31,
172:     30,
173:     31,
174:     30,
175:     31,
176:   ][month - 1];
177:   return day <= daysInMonth;
178: }
