202: export function parseRunOccurrenceId(value: unknown): RunOccurrence | null {
203:   if (typeof value !== "string") return null;
204:   const match = RUN_ID_PATTERN.exec(value);
205:   if (match === null) return null;
206: 
207:   const [, date, rawSequence, actionId] = match;
208:   const sequence = Number(rawSequence);
209:   const occurrence = { date, sequence, actionId };
210:   if (!isRunOccurrence(occurrence)) return null;
211:   if (formatSequence(sequence) !== rawSequence) return null;
212:   return occurrence;
