260: function isJsonValueInternal(
261:   value: unknown,
262:   depth: number,
263:   counter: { nodes: number },
264: ): value is JsonValue {
265:   counter.nodes += 1;
266:   if (counter.nodes > MAX_JSON_NODES || depth > MAX_JSON_DEPTH) return false;
