274:   }
275:   if (typeof value === "number") return Number.isFinite(value);
276: 
277:   if (Array.isArray(value)) {
278:     return value.every((item) => isJsonValueInternal(item, depth + 1, counter));
279:   }
280: 
281:   if (!isRecord(value)) return false;
282:   return Object.values(value).every((item) =>
283:     isJsonValueInternal(item, depth + 1, counter),
284:   );
