410: async function readChangeEntries(changeRoot: string): Promise<string[]> {
411:   try {
412:     const entries = await readdir(changeRoot, { withFileTypes: true });
413:     const names: string[] = [];
414:     for (const entry of entries) {
415:       if (!entry.isDirectory()) {
416:         throw new Error(`Invalid Run history entry: ${entry.name}`);
417:       }
418:       if (parseRunOccurrenceId(entry.name) === null) {
419:         throw new Error(`Invalid Run occurrence directory: ${entry.name}`);
420:       }
421:       names.push(entry.name);
422:     }
423:     return names;
424:   } catch (error) {
425:     if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
426:     throw error;
427:   }
428: }
