430: function assertUniqueSequences(runIds: readonly string[]): void {
431:   const seen = new Set<number>();
432:   for (const runId of runIds) {
433:     const occurrence = parseRunOccurrenceId(runId);
434:     if (occurrence === null) {
435:       throw new Error(`Invalid Run occurrence directory: ${runId}`);
436:     }
437:     if (seen.has(occurrence.sequence)) {
438:       throw new Error(`Duplicate Run sequence: ${occurrence.sequence}`);
439:     }
440:     seen.add(occurrence.sequence);
441:   }
442: }
