444: export async function writeDurableRun(
445:   input: RunAddressInput,
446:   record: DurableRunRecord,
447: ): Promise<RunAddress> {
448:   const address = buildRunAddress(input);
449:   if (address === null) throw new Error("Invalid controlled Run address input");
450:   if (!isActionMarkdown(record.actionMarkdown)) {
451:     throw new Error("Invalid action.md content");
452:   }
453:   if (!isRunContextRecord(record.context)) {
454:     throw new Error("Invalid Run context record");
455:   }
456:   if (!isRunResultRecord(record.result)) {
457:     throw new Error("Invalid Run result record");
458:   }
459:   if (!recordMatchesAddress(address, input, record.context, record.result)) {
460:     throw new Error("Run record linkage does not match generated address");
461:   }
462: 
463:   const existingRunIds = await readChangeEntries(address.changeRoot);
464:   assertUniqueSequences(existingRunIds);
465:   for (const existingRunId of existingRunIds) {
466:     const occurrence = parseRunOccurrenceId(existingRunId)!;
467:     if (occurrence.sequence === input.occurrence.sequence) {
468:       throw new Error(`Run sequence already exists: ${occurrence.sequence}`);
469:     }
470:   }
471: 
472:   await mkdir(address.changeRoot, { recursive: true });
473:   try {
474:     await mkdir(address.runDirectory, { recursive: false });
475:   } catch (error) {
476:     if ((error as NodeJS.ErrnoException).code === "EEXIST") {
477:       throw new Error(`Run occurrence already exists: ${address.runId}`);
478:     }
479:     throw error;
480:   }
481: 
482:   try {
483:     await writeFile(
484:       path.join(address.runDirectory, "action.md"),
485:       record.actionMarkdown,
486:       { encoding: "utf8", flag: "wx" },
487:     );
488:     await writeFile(
489:       path.join(address.runDirectory, "context.json"),
490:       `${JSON.stringify(record.context, null, 2)}\n`,
491:       { encoding: "utf8", flag: "wx" },
492:     );
493:     await writeFile(
494:       path.join(address.runDirectory, "result.json"),
495:       `${JSON.stringify(record.result, null, 2)}\n`,
496:       { encoding: "utf8", flag: "wx" },
497:     );
498:     return address;
499:   } catch (error) {
500:     await rm(address.runDirectory, { recursive: true, force: true });
501:     throw error;
502:   }
503: }
