555: export async function listChangeRunHistory(input: {
556:   readonly repositoryRoot: string;
557:   readonly deliveryId: DeliveryId;
558:   readonly changeId: ChangeId;
559:   readonly changeStartSequence: number;
560: }): Promise<DurableRunRecord[]> {
561:   if (
562:     typeof input.repositoryRoot !== "string" ||
563:     input.repositoryRoot.length === 0 ||
564:     !isSemanticId(input.deliveryId) ||
565:     !isSemanticId(input.changeId) ||
566:     !isRunSequence(input.changeStartSequence)
567:   ) {
568:     throw new Error("Invalid controlled Change Run root input");
569:   }
570: 
571:   const repositoryRoot = path.resolve(input.repositoryRoot);
572:   const changeRoot = path.join(
573:     repositoryRoot,
574:     ".flowkit",
575:     "runs",
576:     input.deliveryId,
577:     `${formatSequence(input.changeStartSequence)}-${input.changeId}`,
578:   );
579:   const runIds = await readChangeEntries(changeRoot);
580:   assertUniqueSequences(runIds);
